def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    """
    Given a string representing a space separated lowercase letters, 
    return a dictionary of the letter with the most repetition and 
    containing the corresponding count. If several letters have the 
    same occurrence, return all of them.

    Args:
        test (str): A string of space separated lowercase letters.

    Returns:
        dict: A dictionary with the most repeated letters and their counts.
    """
    # Split the input string into a list of letters
    letters = test.split()

    # Initialize an empty dictionary to store the count of each letter
    letter_count = {}

    # Count the occurrences of each letter
    for letter in letters:
        if letter in letter_count:
            letter_count[letter] += 1
        else:
            letter_count[letter] = 1

    # If the input string is empty, return an empty dictionary
    if not letter_count:
        return {}

    # Find the maximum count
    max_count = max(letter_count.values())

    # Return a dictionary with the letters that have the maximum count
    return {letter: count for letter, count in letter_count.items() if count == max_count}
